public Telekinesis(){
	super("telekinesis", SpellActions.POINT, false);
	this.aimAssist(0.4f); // Helps with aiming at items
}

	protected boolean onEntityHit(World world, Entity target, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

		if(target instanceof EntityItem){

			target.motionX = (origin.x - target.posX) / 6;
			target.motionY = (origin.y - target.posY) / 6;
			target.motionZ = (origin.z - target.posZ) / 6;
			return true;

		} else if (target instanceof EntityPlayer && (Wizardry.settings.telekineticDisarmament && !ItemArtefact.isArtefactActive((EntityPlayer) target, WizardryItems.amulet_anchoring))) {

      EntityPlayer player = (EntityPlayer) target;

			// IDEA: Disarm the offhand if the mainhand is empty or otherwise harmless?

			if (!player.getHeldItemMainhand().isEmpty()) {

				if (!world.isRemote) {
					EntityItem item = player.entityDropItem(player.getHeldItemMainhand(), 0);
					// Makes the item move towards the caster
					item.motionX = (origin.x - player.posX) / 20;
					item.motionZ = (origin.z - player.posZ) / 20;
				}

				player.setHeldItem(EnumHand.MAIN_HAND, ItemStack.EMPTY);

				return true;
			}
		}

		return false;
	}

protected boolean onBlockHit(World world, BlockPos pos, EnumFacing side, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	if(caster instanceof EntityPlayer){

		IBlockState blockstate = world.getBlockState(pos);

		if(blockstate.getBlock().onBlockActivated(world, pos, blockstate, (EntityPlayer)caster, EnumHand.MAIN_HAND,
				side, 0, 0, 0)){
			return true;
		}
	}

	return false;
}

protected boolean onMiss(World world, EntityLivingBase caster, Vec3d origin, Vec3d direction, int ticksInUse, SpellModifiers modifiers){
	return false;
}

public ActionResult<ItemStack> onItemRightClick(World world, EntityPlayer player, EnumHand hand){

	ItemStack stack = player.getHeldItem(hand);

	// Alternate right-click function; overrides spell casting.
	if(this.selectMinionTarget(player, world)) return new ActionResult<>(EnumActionResult.SUCCESS, stack);

	Spell spell = WandHelper.getCurrentSpell(stack);
	SpellModifiers modifiers = this.calculateModifiers(stack, player, spell);

	if(canCast(stack, spell, player, hand, 0, modifiers)){
		// Need to account for the modifier since it could be zero even if the original charge-up wasn't
		int chargeup = (int)(spell.getChargeup() * modifiers.get(SpellModifiers.CHARGEUP));

		if(spell.isContinuous || chargeup > 0){
			// Spells that need the mouse to be held (continuous, charge-up or both)
			if(!player.isHandActive()){
				player.setActiveHand(hand);
				// Store the modifiers for use later
				if(WizardData.get(player) != null) WizardData.get(player).itemCastingModifiers = modifiers;
				if(chargeup > 0 && world.isRemote) Wizardry.proxy.playChargeupSound(player);
				return new ActionResult<>(EnumActionResult.SUCCESS, stack);
			}
		}else{
			// All other (instant) spells
			if(cast(stack, spell, player, hand, 0, modifiers)){
				return new ActionResult<>(EnumActionResult.SUCCESS, stack);
			}
		}
	}

	return new ActionResult<>(EnumActionResult.FAIL, stack);
}

public boolean canCast(ItemStack stack, Spell spell, EntityPlayer caster, EnumHand hand, int castingTick, SpellModifiers modifiers){

	// Spells can only be cast if the casting events aren't cancelled...
	if(castingTick == 0){
		if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Pre(Source.WAND, spell, caster, modifiers))) return false;
	}else{
		if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Tick(Source.WAND, spell, caster, modifiers, castingTick))) return false;
	}

	int cost = (int)(spell.getCost() * modifiers.get(SpellModifiers.COST) + 0.1f); // Weird floaty rounding

	// As of wizardry 4.2 mana cost is only divided over two intervals each second
	if(spell.isContinuous) cost = getDistributedCost(cost, castingTick);

	// ...and the wand has enough mana to cast the spell...
	return cost <= this.getMana(stack) // This comes first because it changes over time
			// ...and the wand is the same tier as the spell or higher...
			&& spell.getTier().level <= this.tier.level
			// ...and either the spell is not in cooldown or the player is in creative mode
			&& (WandHelper.getCurrentCooldown(stack) == 0 || caster.isCreative());
}

public boolean cast(ItemStack stack, Spell spell, EntityPlayer caster, EnumHand hand, int castingTick, SpellModifiers modifiers){

	World world = caster.world;

	if(world.isRemote && !spell.isContinuous && spell.requiresPacket()) return false;

	if(spell.cast(world, caster, hand, castingTick, modifiers)){

		if(castingTick == 0) MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.WAND, spell, caster, modifiers));

		if(!world.isRemote){

			// Continuous spells never require packets so don't rely on the requiresPacket method to specify it
			if(!spell.isContinuous && spell.requiresPacket()){
				// Sends a packet to all players in dimension to tell them to spawn particles.
				IMessage msg = new PacketCastSpell.Message(caster.getEntityId(), hand, spell, modifiers);
				WizardryPacketHandler.net.sendToDimension(msg, world.provider.getDimension());
			}

			// Mana cost
			int cost = (int)(spell.getCost() * modifiers.get(SpellModifiers.COST) + 0.1f); // Weird floaty rounding
			// As of wizardry 4.2 mana cost is only divided over two intervals each second
			if(spell.isContinuous) cost = getDistributedCost(cost, castingTick);

			if(cost > 0) this.consumeMana(stack, cost, caster);

		}

		caster.setActiveHand(hand);

		// Cooldown
		if(!spell.isContinuous && !caster.isCreative()){ // Spells only have a cooldown in survival
			WandHelper.setCurrentCooldown(stack, (int)(spell.getCooldown() * modifiers.get(WizardryItems.cooldown_upgrade)));
		}

		// Progression
		if(this.tier.level < Tier.MASTER.level && castingTick % CONTINUOUS_TRACKING_INTERVAL == 0){

			// We don't care about cost modifiers here, otherwise players would be penalised for wearing robes!
			int progression = (int)(spell.getCost() * modifiers.get(SpellModifiers.PROGRESSION));
			WandHelper.addProgression(stack, progression);

			if(!Wizardry.settings.legacyWandLevelling){ // Don't display the message if legacy wand levelling is enabled
				// If the wand just gained enough progression to be upgraded...
				Tier nextTier = tier.next();
				int excess = WandHelper.getProgression(stack) - nextTier.getProgression();
				if(excess >= 0 && excess < progression){
					// ...display a message above the player's hotbar
					caster.playSound(WizardrySounds.ITEM_WAND_LEVELUP, 1.25f, 1);
					WizardryAdvancementTriggers.wand_levelup.triggerFor(caster);
					if(!world.isRemote)
						caster.sendMessage(new TextComponentTranslation("item." + Wizardry.MODID + ":wand.levelup",
								this.getItemStackDisplayName(stack), nextTier.getNameForTranslationFormatted()));
				}
			}

			WizardData.get(caster).trackRecentSpell(spell);
		}

		return true;
	}

	return false;
}

public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	Vec3d look = caster.getLookVec();
	Vec3d origin = new Vec3d(caster.posX, caster.posY + caster.getEyeHeight() - Y_OFFSET, caster.posZ);
	if(!this.isContinuous && world.isRemote && !Wizardry.proxy.isFirstPerson(caster)){
		origin = origin.add(look.scale(1.2));
	}

	if(!shootSpell(world, origin, look, caster, ticksInUse, modifiers)) return false;

	if(casterSwingsArm(world, caster, hand, ticksInUse, modifiers)) caster.swingArm(hand);
	this.playSound(world, caster, ticksInUse, -1, modifiers);
	return true;
}

protected boolean shootSpell(World world, Vec3d origin, Vec3d direction, @Nullable EntityLivingBase caster, int ticksInUse, SpellModifiers modifiers){

	double range = getRange(world, origin, direction, caster, ticksInUse, modifiers);
	Vec3d endpoint = origin.add(direction.scale(range));

	// Change the filter depending on whether living entities are ignored or not
	RayTraceResult rayTrace = RayTracer.rayTrace(world, origin, endpoint, aimAssist, hitLiquids,
			ignoreUncollidables, false, Entity.class, ignoreLivingEntities ? EntityUtils::isLiving
			: RayTracer.ignoreEntityFilter(caster));

	boolean flag = false;

	if(rayTrace != null){
		// Doesn't matter which way round these are, they're mutually exclusive
		if(rayTrace.typeOfHit == RayTraceResult.Type.ENTITY){
			// Do whatever the spell does when it hits an entity
			// FIXME: Some spells (e.g. lightning web) seem to not render when aimed at item frames
			flag = onEntityHit(world, rayTrace.entityHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// If the spell succeeded, clip the particles to the correct distance so they don't go through the entity
			if(flag) range = origin.distanceTo(rayTrace.hitVec);

		}else if(rayTrace.typeOfHit == RayTraceResult.Type.BLOCK){
			// Do whatever the spell does when it hits an block
			flag = onBlockHit(world, rayTrace.getBlockPos(), rayTrace.sideHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// Clip the particles to the correct distance so they don't go through the block
			// Unlike with entities, this is done regardless of whether the spell succeeded, since no spells go
			// through blocks (and in fact, even the ray tracer itself doesn't do that)
			range = origin.distanceTo(rayTrace.hitVec);
		}
	}

	// If flag is false, either the spell missed or the relevant entity/block hit method returned false
	if(!flag && !onMiss(world, caster, origin, direction, ticksInUse, modifiers)) return false;

	// Particle spawning
	if(world.isRemote){
		spawnParticleRay(world, origin, direction, caster, range);
	}

	return true;
}

public static boolean isArtefactActive(EntityPlayer player, Item artefact){

	if(!(artefact instanceof ItemArtefact)) throw new IllegalArgumentException("Not an artefact!");

	if(!((ItemArtefact)artefact).enabled) return false; // Disabled in the config

	ArtefactCheckEvent event = new ArtefactCheckEvent(player, (ItemArtefact) artefact);
	if(MinecraftForge.EVENT_BUS.post(event)) return false;

	if (event.getResult() == Event.Result.ALLOW) {
		return true;
	}

	if(WizardryBaublesIntegration.enabled()){
		return WizardryBaublesIntegration.isBaubleEquipped(player, artefact);
	}else{
		// To find out if the given artefact is one of the first n on the player's hotbar (where n is the maximum
		// number of that kind of artefact that can be active at once):
		return InventoryUtils.getPrioritisedHotbarAndOffhand(player).stream() // Retrieve the stacks in question
				// Filter out all except artefacts of the same type as the given one (preserving order)
				.filter(s -> s.getItem() instanceof ItemArtefact && ((ItemArtefact)s.getItem()).type == ((ItemArtefact)artefact).type)
				.limit(((ItemArtefact)artefact).type.maxAtOnce)    // Ignore all but the first n
				.anyMatch(s -> s.getItem() == artefact); // Check if the remaining stacks contain the artefact
		// Note that streaming a list DOES retain the order (unless you call unordered(), obviously)
	}
}

public static List<ItemStack> getHotbar(EntityPlayer player){
	NonNullList<ItemStack> hotbar = NonNullList.create();
	hotbar.addAll(player.inventory.mainInventory.subList(0, 9));
	return hotbar;
}

public static List<ItemStack> getPrioritisedHotbarAndOffhand(EntityPlayer player){
	List<ItemStack> hotbar = getHotbar(player);
	// Adds the offhand item to the beginning of the list so it is processed before the hotbar
	hotbar.add(0, player.getHeldItemOffhand());
	// Moves the item in the main hand to the beginning of the list so it is processed first
	hotbar.remove(player.getHeldItemMainhand());
	hotbar.add(0, player.getHeldItemMainhand());
	return hotbar;
}

public static boolean enabled(){
	return Wizardry.settings.baublesIntegration && baublesLoaded;
}

public static boolean isBaubleEquipped(EntityPlayer player, Item item){
	return BaublesApi.isBaubleEquipped(player, item) >= 0;
}

public RenderDecoy(RenderManager manager){
	super(manager, new ModelBiped(0.0f), 0.5f);
}

public void doRender(EntityDecoy entity, double x, double y, double z, float entityYaw, float partialTicks){

	if(entity.getCaster() != null){

		this.renderName(entity, x, y, z);

		// Save relevant animation fields from the caster to local variables
		float pitch = entity.getCaster().rotationPitch;
		float prevPitch = entity.getCaster().prevRotationPitch;
		float swing = entity.getCaster().swingProgress;
		float prevSwing = entity.getCaster().prevSwingProgress;
		float yawOffset = entity.getCaster().renderYawOffset;
		float prevYawOffset = entity.getCaster().prevRenderYawOffset;
		float yaw = entity.getCaster().rotationYawHead;
		float prevYaw = entity.getCaster().prevRotationYawHead;
		float limbSwing = entity.getCaster().limbSwing;
		float limbSwingAmount = entity.getCaster().limbSwingAmount;
		float prevLimbSwingAmount = entity.getCaster().prevLimbSwingAmount;
		int hurtTime = entity.getCaster().hurtTime;
		boolean sneak = entity.getCaster().isSneaking();
		Entity mount = entity.getCaster().getRidingEntity();

		// Assign decoy's animation fields to the caster
		entity.getCaster().rotationPitch = entity.rotationPitch;
		entity.getCaster().prevRotationPitch = entity.prevRotationPitch;
		entity.getCaster().swingProgress = entity.swingProgress;
		entity.getCaster().prevSwingProgress = entity.prevSwingProgress;
		entity.getCaster().renderYawOffset = entity.renderYawOffset;
		entity.getCaster().prevRenderYawOffset = entity.prevRenderYawOffset;
		entity.getCaster().rotationYawHead = entity.rotationYawHead;
		entity.getCaster().prevRotationYawHead = entity.prevRotationYawHead;
		entity.getCaster().limbSwing = entity.limbSwing;
		entity.getCaster().limbSwingAmount = entity.limbSwingAmount;
		entity.getCaster().prevLimbSwingAmount = entity.prevLimbSwingAmount;
		entity.getCaster().hurtTime = entity.hurtTime;
		entity.getCaster().setSneaking(false); // Decoys can't sneak FIXME Not working!
		entity.getCaster().dismountRidingEntity(); // Decoys can't ride anything

		// Do the rendering
		renderManager.getEntityRenderObject(entity.getCaster()).doRender(entity.getCaster(), x, y, z, entityYaw,
				partialTicks);

		// Reset caster's animation fields to their original values
		entity.getCaster().rotationPitch = pitch;
		entity.getCaster().prevRotationPitch = prevPitch;
		entity.getCaster().swingProgress = swing;
		entity.getCaster().prevSwingProgress = prevSwing;
		entity.getCaster().renderYawOffset = yawOffset;
		entity.getCaster().prevRenderYawOffset = prevYawOffset;
		entity.getCaster().rotationYawHead = yaw;
		entity.getCaster().prevRotationYawHead = prevYaw;
		entity.getCaster().limbSwing = limbSwing;
		entity.getCaster().limbSwingAmount = limbSwingAmount;
		entity.getCaster().prevLimbSwingAmount = prevLimbSwingAmount;
		entity.getCaster().hurtTime = hurtTime;
		entity.getCaster().setSneaking(sneak);
		if(mount != null) entity.getCaster().startRiding(mount);

	}else{
		super.doRender(entity, x, y, z, entityYaw, partialTicks);
	}
}

protected ResourceLocation getEntityTexture(EntityDecoy entity){
	if(entity.getCaster() != null){
		try{
			return (ResourceLocation)getEntityTexture
					.invoke(renderManager.getEntityRenderObject(entity.getCaster()));
		}catch (IllegalAccessException | IllegalArgumentException | InvocationTargetException
				| ClassCastException e){
			Wizardry.logger
					.error("Error while reflectively calling Render#getEntityTexture as part of decoy rendering");
			e.printStackTrace();
		}
	}
	// Fallback to steve textures
	return steveTextures;
}

public void setCaster(EntityLivingBase caster){
	super.setCaster(caster);
	this.setAlwaysRenderNameTag(caster instanceof EntityPlayer);
}

public boolean isEntityInvulnerable(DamageSource source){
	return true;
}

public void onUpdate(){
	super.onUpdate();
	if(this.getCaster() == null || this.getCaster().isDead){
		this.setDead();
		this.onDespawn();
	}
}

public void onDespawn(){
	super.onDespawn();

	if(world.isRemote){
		for(int i = 0; i < 20; i++){
			ParticleBuilder.create(Type.DUST)
			.pos(this.posX + (this.rand.nextDouble() - 0.5) * this.width, this.posY
					+ this.rand.nextDouble() * this.height, this.posZ + (this.rand.nextDouble() - 0.5) * this.width)
			.time(40)
			.clr(0.2f, 1.0f, 0.8f)
			.shaded(true)
			.spawn(world);
		}
	}
}

default EntityLivingBase getCaster(){ // Kept despite the above method because it returns an EntityLivingBase

	if(this instanceof Entity){ // Bit of a cheat but it saves having yet another method just to get the world

		Entity entity = EntityUtils.getEntityByUUID(((Entity)this).world, getOwnerId());

		if(entity != null && !(entity instanceof EntityLivingBase)){ // Should never happen
			Wizardry.logger.warn("{} has a non-living owner!", this);
			return null;
		}

		return (EntityLivingBase)entity;

	}else{
		Wizardry.logger.warn("{} implements ISummonedCreature but is not an SoundLoopSpellEntity!", this.getClass());
		return null;
	}
}

default void writeSpawnData(ByteBuf buffer){
	buffer.writeInt(getCaster() != null ? getCaster().getEntityId() : -1);
	buffer.writeInt(getLifetime());
}

default void readSpawnData(ByteBuf buffer){
	int id = buffer.readInt();
	// We're on the client side here, so we can safely use Minecraft.getMinecraft().world via proxies.
	if(id > -1){
		Entity entity = Wizardry.proxy.getTheWorld().getEntityByID(id);
		if(entity instanceof EntityLivingBase) setCaster((EntityLivingBase)entity);
		else Wizardry.logger.warn("Received a spawn packet for entity {}, but no living entity matched the supplied ID", this);
	}
	setLifetime(buffer.readInt());
}

default void writeNBTDelegate(NBTTagCompound tagcompound){
	if(this.getCaster() != null){
		tagcompound.setUniqueId("casterUUID", this.getCaster().getUniqueID());
	}
	tagcompound.setInteger("lifetime", getLifetime());
}

default void readNBTDelegate(NBTTagCompound tagcompound){
	this.setOwnerId(tagcompound.getUniqueId("casterUUID"));
	this.setLifetime(tagcompound.getInteger("lifetime"));
}

default void updateDelegate(){

	if(!(this instanceof Entity))
		throw new ClassCastException("Implementations of ISummonedCreature must extend SoundLoopSpellEntity!");

	Entity thisEntity = ((Entity)this);

	if(thisEntity.ticksExisted == 1){
		this.onSpawn();
	}

	// For some reason Minecraft reads the entity from NBT just after the entity is created, so setting -1 as a
	// default lifetime doesn't work. The easiest way around this is to use 0 - nobody's going to need it!
	if(thisEntity.ticksExisted > this.getLifetime() && this.getLifetime() > 0){
		this.onDespawn();
		thisEntity.setDead();
	}

	if(this.hasParticleEffect() && thisEntity.world.isRemote && thisEntity.world.rand.nextInt(8) == 0)
		ParticleBuilder.create(Type.DARK_MAGIC)
		.pos(thisEntity.posX, thisEntity.posY + thisEntity.world.rand.nextDouble() * 1.5, thisEntity.posZ)
		.clr(0.1f, 0.0f, 0.0f)
		.spawn(thisEntity.world);

}

public static Entity getEntityByUUID(World world, @Nullable UUID id){

	if(id == null) return null; // It would return null eventually but there's no point even looking

	for(Entity entity : world.loadedEntityList){
		// This is a perfect example of where you need to use .equals() and not ==. For most applications,
		// this was unnoticeable until world reload because the UUID instance or entity instance is stored.
		// Fixed now though.
		if(entity != null && entity.getUniqueID() != null && entity.getUniqueID().equals(id)){
			return entity;
		}
	}
	return null;
}

public static <T extends Entity> List<T> getEntitiesWithinRadius(double radius, double x, double y, double z, World world, Class<T> entityType){
	AxisAlignedBB aabb = new AxisAlignedBB(x - radius, y - radius, z - radius, x + radius, y + radius, z + radius);
	List<T> entityList = world.getEntitiesWithinAABB(entityType, aabb);
	for(int i = 0; i < entityList.size(); i++){
		if(entityList.get(i).getDistance(x, y, z) > radius){
			entityList.remove(i);
			break;
		}
	}
	return entityList;
}
